-- single transaction at first boot.
CREATE TABLE public.alert_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    project_id uuid NOT NULL,
    name text NOT NULL,
    rule_type text DEFAULT 'issue-frequency'::text NOT NULL,
    level text,
    threshold integer DEFAULT 1 NOT NULL,
    window_seconds integer DEFAULT 60 NOT NULL,
    fingerprint_filter text,
    scope text DEFAULT 'project'::text NOT NULL,
    environment text,
    channels jsonb DEFAULT '[]'::jsonb NOT NULL,
    owners jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    last_triggered_at timestamp with time zone,
    trigger_count_7d integer DEFAULT 0 NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    notification_channel text DEFAULT 'email'::text NOT NULL,
    notification_target text,
    condition_type text,
    condition_value text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


